        self.cache = {}  # Maps keys to (value, frequency)
        self.freq = defaultdict(OrderedDict)  # Maps frequency to keys
        self.min_freq = 0  # Minimum frequency of any key in the cache

    def get(self, key):
        if key not in self.cache:
            return None
        value, freq = self.cache[key]
