def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  ' * indent
    output = f"{indent_str}{self.__class__.__name__}(\n"
    for attr, value in self.__dict__.items():
        if isinstance(value, list):
            output += f"{indent_str}  {attr}=[\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    output += item.pretty(indent + 2, debug) + ",\n"
                else:
                    output += f"{indent_str}    {item},\n"
            output += f"{indent_str}  ],\n"
        elif hasattr(value, 'pretty'):
            output += f"{indent_str}  {attr}={value.pretty(indent + 2, debug)},\n"
        else:
            output += f"{indent_str}  {attr}={value},\n"
    output += f"{indent_str})"
    return output
